INSERT INTO extracurriculars (group_id,name,slug,short_description,description,is_featured) VALUES
(1,'ECC — English Conversation Club','ecc','Ruang praktik bahasa Inggris dan komunikasi percaya diri.','English Conversation Club mendukung latihan percakapan, presentasi, dan kegiatan bahasa Inggris.',1),(1,'Nihongo','nihongo','Komunitas pembelajaran bahasa dan budaya Jepang.','Nihongo menjadi ruang belajar bahasa serta pengenalan budaya Jepang.',0),(2,'Ambalan','ambalan','Kepramukaan untuk kepemimpinan dan pengabdian.','Ambalan mengembangkan keterampilan kepramukaan, kepemimpinan, dan pengabdian.',1),(2,'Paskib','paskib','Latihan disiplin, kepemimpinan, dan baris-berbaris.','Paskib membina disiplin serta keterampilan baris-berbaris.',1),(2,'PMR','pmr','Kegiatan kemanusiaan dan keterampilan kesehatan remaja.','PMR menumbuhkan kepedulian kemanusiaan dan keterampilan kesehatan.',0),(3,'Remas','remas','Kegiatan kerohanian dan pelayanan siswa.','Remas memfasilitasi kegiatan kerohanian siswa.',0),(3,'Banjari','banjari','Seni musik religi dan kebersamaan.','Banjari mengembangkan seni musik religi.',0),(4,'PIK-R','pik-r','Pusat informasi dan konseling remaja.','PIK-R menjadi ruang edukasi dan konseling remaja.',0),(5,'Basket','basket','Latihan bola basket dan sportivitas.','Basket mengembangkan teknik, kerja tim, dan sportivitas.',1),(5,'Dance','dance','Ekspresi gerak dan pertunjukan.','Dance menjadi ruang latihan koreografi dan pertunjukan.',0),(5,'E-Sport','e-sport','Kompetisi digital yang konfigurabel sesuai kebijakan sekolah.','E-Sport dikelola secara konfigurabel tanpa mengikat pada satu judul permainan.',0),(5,'Futsal','futsal','Latihan futsal dan kerja sama tim.','Futsal mengembangkan teknik bermain dan kerja sama.',0),(5,'Gateball','gateball','Olahraga strategi dan ketelitian.','Gateball melatih strategi dan ketelitian.',0),(5,'Karate','karate','Seni bela diri, disiplin, dan kebugaran.','Karate mengembangkan teknik bela diri serta karakter disiplin.',0),(5,'Pencak Silat','pencak-silat','Seni bela diri tradisional Indonesia.','Pencak Silat melatih keterampilan bela diri dan pelestarian budaya.',0),(5,'Spartan','spartan','Organisasi pendukung kegiatan sekolah.','Spartan adalah organisasi pendukung sekolah; pengelompokan olahraga bersifat administratif.',0),(5,'Volly','volly','Latihan bola voli dan kolaborasi tim.','Volly mengembangkan kemampuan teknik dan kerja tim.',0),(6,'Teater','teater','Seni peran, produksi, dan pertunjukan.','Teater mengembangkan ekspresi, produksi, dan kerja kreatif.',0),(7,'Karawitan','karawitan','Pelestarian seni musik tradisional.','Karawitan menjadi ruang mempelajari musik tradisional.',0),(7,'Multimedia','multimedia','Kreasi visual, media, dan dokumentasi.','Multimedia mengembangkan produksi media kreatif.',1),(7,'Music','music','Komunitas musik dan pertunjukan siswa.','Music mengembangkan keterampilan bermusik serta pertunjukan.',1),(7,'Paduan Suara','paduan-suara','Latihan vokal dan harmoni kelompok.','Paduan Suara mengembangkan kemampuan vokal dan harmoni.',0),(7,'Tari','tari','Seni tari dan ekspresi budaya.','Tari mengembangkan keterampilan gerak dan ekspresi budaya.',0),(8,'LKTI — Lomba Karya Tulis Ilmiah','lkti','Riset, penulisan, dan kompetisi ilmiah.','LKTI mendukung riset dan penulisan karya ilmiah.',1),(8,'Spekta','spekta','Budidaya tanaman dari penanaman hingga panen.','Spekta berfokus pada penanaman, perawatan, dan panen tanaman.',0),(9,'Kopsis — Koperasi Siswa','kopsis','Pembelajaran tata kelola koperasi siswa.','Kopsis mengenalkan pengelolaan usaha koperasi siswa.',0),(9,'Kewirausahaan','kewirausahaan','Pembelajaran usaha kreatif dan mandiri.','Kewirausahaan mengembangkan keterampilan usaha siswa.',0);
